const PALETTE_EXAMPLE=['#FFD93D','#FF6B6B','#6BCB77','#4D96FF','#FF9F45','#B983FF','#FF6FB5','#00C9A7'];
const FESTIVAL_COLORS=[{name:'Emas',hex:'#d4af37'},{name:'Hijau Zamrud',hex:'#047857'},{name:'Biru Dongker',hex:'#1e3a8a'},{name:'Maroon',hex:'#7f1d1d'},{name:'Krem',hex:'#fef3c7'},{name:'Toska',hex:'#0f766e'}];
const SCENERY_PALETTE=['#7dd3fc','#4ade80','#facc15','#a16207','#f97316','#ffffff','#fda4af','#38bdf8','#86efac','#fbbf24'];
function templateSvg(t:Template,mode:'outline'|'preview'|'colored',palette:string[]=PALETTE_EXAMPLE){
  if(mode==='outline') return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000">${t.svg.replace(/fill="F\d+"/g,'fill="none"')}</svg>`;
  if(mode==='preview') return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000"><rect width="1000" height="1000" fill="#ffffff"/>${t.svg.replace(/fill="F(\d+)"/g,()=>`fill="#ffffff"`)}</svg>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 1000">${t.svg.replace(/fill="F(\d+)"/g,(_,n)=>`fill="${palette[Number(n)%palette.length]}"`)}</svg>`;
}
function templateUrl(t:Template,mode:'outline'|'preview'|'colored',palette?:string[]){ return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(templateSvg(t,mode,palette))}`; }
function stickerSvg(kind:string){
  if(kind==='heart') return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><path d="M100 170 Q20 110 20 60 Q20 20 60 20 Q100 20 100 55 Q100 20 140 20 Q180 20 180 60 Q180 110 100 170" fill="#ec4899" stroke="#111" stroke-width="8"/></svg>`;
  if(kind==='flower') return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><circle cx="100" cy="55" r="35" fill="#facc15" stroke="#111" stroke-width="7"/><circle cx="145" cy="100" r="35" fill="#f97316" stroke="#111" stroke-width="7"/><circle cx="100" cy="145" r="35" fill="#ec4899" stroke="#111" stroke-width="7"/><circle cx="55" cy="100" r="35" fill="#22c55e" stroke="#111" stroke-width="7"/><circle cx="100" cy="100" r="30" fill="#fff" stroke="#111" stroke-width="7"/></svg>`;
  if(kind==='butterfly') return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><path d="M95 70 Q30 20 25 80 Q20 140 95 115 M105 70 Q170 20 175 80 Q180 140 105 115" fill="#8b5cf6" stroke="#111" stroke-width="7"/><ellipse cx="100" cy="100" rx="12" ry="45" fill="#111"/><circle cx="100" cy="45" r="12" fill="#111"/></svg>`;
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200"><path d="M100 20 L125 75 L185 80 L138 118 L152 180 L100 148 L48 180 L62 118 L15 80 L75 75 Z" fill="#facc15" stroke="#111" stroke-width="8" stroke-linejoin="round"/></svg>`;
}
const uid=()=>Math.random().toString(36).slice(2)+Date.now().toString(36);
function hexToRgb(hex:string){const h=hex.replace('#','');const n=parseInt(h.length===3?h.split('').map(c=>c+c).join(''):h,16);return {r:(n>>16)&255,g:(n>>8)&255,b:n&255}}
function rgbToHex(r:number,g:number,b:number){return '#'+[r,g,b].map(v=>Math.round(v).toString(16).padStart(2,'0')).join('')}
function loadSvgImage(svg:string){return new Promise<HTMLImageElement>((res,rej)=>{const img=new Image();img.onload=()=>res(img);img.onerror=()=>rej(new Error('gagal'));img.src=`data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`;});}
function drawStarPath(ctx:CanvasRenderingContext2D,cx:number,cy:number,rx:number,ry:number){ ctx.beginPath(); for(let i=0;i<10;i++){ const r=i%2===0?1:0.45; const a=-Math.PI/2+i*Math.PI/5; const x=cx+Math.cos(a)*rx*r, y=cy+Math.sin(a)*ry*r; if(i===0) ctx.moveTo(x,y); else ctx.lineTo(x,y); } ctx.closePath(); }
function drawHeartPath(ctx:CanvasRenderingContext2D,x:number,y:number,w:number,h:number){ const cx=x+w/2, top=y+h*0.28; ctx.beginPath(); ctx.moveTo(cx,y+h*0.92); ctx.bezierCurveTo(x-w*0.15,y+h*0.45,x+w*0.12,y-h*0.08,cx,top); ctx.bezierCurveTo(x+w*0.88,y-h*0.08,x+w*1.15,y+h*0.45,cx,y+h*0.92); ctx.closePath(); }

