 const findInList=(list:CanvasObject[],id:string):CanvasObject|null=>{ for(const o of list){ if(o.id===id) return o; if(o.kind==='group'&&o.data?.children){ const f=findInList(o.data.children,id); if(f) return f; } } return null; };
 const findParentInList=(list:CanvasObject[],id:string,parent:CanvasObject|null=null):CanvasObject|null=>{ for(const o of list){ if(o.id===id) return parent; if(o.kind==='group'&&o.data?.children){ const f=findParentInList(o.data.children,id,o); if(f!==null||findInList(o.data.children,id)) return f!==null?f:o; } } return null; };
 const countGroup=(o:CanvasObject):number=> o.kind==='group'?(o.data?.children||[]).reduce((n:number,c:CanvasObject)=>n+countGroup(c),0)+(o.data?.children||[]).length : 0;
 const flattenGroups=(list:CanvasObject[],out:CanvasObject[]=[]):CanvasObject[]=>{ for(const o of list){ out.push(o); if(o.kind==='group'&&o.data?.children) flattenGroups(o.data.children,out); } return out; };
 const groupBBox=(children:CanvasObject[])=>{ if(!children.length) return {x:0,y:0,w:0,h:0}; const minX=Math.min(...children.map(c=>c.x)),minY=Math.min(...children.map(c=>c.y)),maxX=Math.max(...children.map(c=>c.x+c.w)),maxY=Math.max(...children.map(c=>c.y+c.h)); return {x:minX,y:minY,w:Math.max(1,maxX-minX),h:Math.max(1,maxY-minY)}; };
 const cloneWithNewIds=(o:CanvasObject):CanvasObject=>{ const c=JSON.parse(JSON.stringify(o)); const assign=(x:CanvasObject)=>{ x.id=uid(); if(x.kind==='group'&&x.data?.children) x.data.children.forEach(assign); }; assign(c); return c; };
 const rotatePoint=(px:number,py:number,cx:number,cy:number,deg:number)=>{ const r=deg*Math.PI/180; const dx=px-cx,dy=py-cy; return {x:cx+dx*Math.cos(r)-dy*Math.sin(r), y:cy+dx*Math.sin(r)+dy*Math.cos(r)}; };
 const applyGroupRotationToChildren=(g:CanvasObject):CanvasObject[]=>{ if(!g.rotation) return JSON.parse(JSON.stringify(g.data?.children||[])); const cx=g.x+g.w/2, cy=g.y+g.h/2; return (g.data?.children||[]).map((ch:CanvasObject)=>{ const cc=rotatePoint(ch.x+ch.w/2,ch.y+ch.h/2,cx,cy,g.rotation); return {...JSON.parse(JSON.stringify(ch)), x:cc.x-ch.w/2, y:cc.y-ch.h/2, rotation:((ch.rotation+g.rotation)%360+360)%360}; }); };
 const setSnap=(g:SnapGuide[],info:string)=>{ snapGuidesRef.current=g; setSnapGuidesState(g); setSnapInfo(info); };
 const clearSnap=()=>{ if(snapGuidesRef.current.length||snapInfo){ snapGuidesRef.current=[]; setSnapGuidesState([]); setSnapInfo(''); } };
