 const drawOneObject=(ctx:CanvasRenderingContext2D,o:CanvasObject,dimmed=false)=>{
   if(o.kind==='template') return;
   if(o.kind==='group'){ ctx.save(); ctx.translate(o.x+o.w/2,o.y+o.h/2); ctx.rotate(o.rotation*Math.PI/180); ctx.translate(-(o.x+o.w/2),-(o.y+o.h/2)); for(const ch of (o.data?.children||[])) drawOneObject(ctx,ch,dimmed); ctx.restore(); ctx.globalAlpha=1; return; }
   ctx.save(); ctx.translate(o.x+o.w/2,o.y+o.h/2); ctx.rotate(o.rotation*Math.PI/180); ctx.globalAlpha=(o.opacity/100)*(dimmed?0.3:1);
   if(o.kind==='text'){ const d=o.data||{}; const opt=fontOptionFor(d.font||'Plus Jakarta Sans'); ctx.fillStyle=d.color||'#111827'; ctx.font=`${d.italic?'italic ':''}${d.bold?'700':opt.weight} ${d.size||48}px ${fontFamilyFor(d.font||'Plus Jakarta Sans')}`; ctx.textAlign=(d.align||'center') as CanvasTextAlign; ctx.textBaseline='middle'; const txt=String(d.text||''); ctx.fillText(txt,0,0,Math.max(10,o.w)); if(d.underline){ const w=ctx.measureText(txt).width; const y=(d.size||48)*0.52; const x0=d.align==='left'?0:d.align==='right'?-w:-w/2; ctx.strokeStyle=d.color||'#111827'; ctx.lineWidth=Math.max(1.5,(d.size||48)*0.06); ctx.beginPath(); ctx.moveTo(x0,y); ctx.lineTo(x0+w,y); ctx.stroke(); } }
   else if(o.kind==='sticker'){ const img=imageCacheRef.current['sticker:'+(o.data?.kind||'')]; if(img) ctx.drawImage(img,-o.w/2,-o.h/2,o.w,o.h); else { loadSvgImage(stickerSvg(o.data?.kind||'star')).then(im=>{imageCacheRef.current['sticker:'+(o.data?.kind||'')]=im; composite();}).catch(()=>{}); } }
   else if(o.kind==='area'||o.kind==='image'){ const key='img:'+(o.data?.img||'').slice(0,80); let img=imageCacheRef.current[key]; if(!img&&o.data?.img){ img=new Image(); img.onload=()=>composite(); img.src=o.data.img; imageCacheRef.current[key]=img; } if(img&&img.complete&&img.naturalWidth) ctx.drawImage(img,-o.w/2,-o.h/2,o.w,o.h); }
   else if(o.kind==='shape'){ const d=o.data||{}; ctx.strokeStyle=d.color||'#111827'; ctx.fillStyle=d.color||'#111827'; ctx.lineWidth=d.lineWidth||8; ctx.lineCap='round'; ctx.lineJoin='round'; if(d.shape==='line'){ctx.beginPath();ctx.moveTo(-o.w/2,-o.h/2);ctx.lineTo(o.w/2,o.h/2);ctx.stroke();} else if(d.shape==='rect'){ if(d.fill) ctx.fillRect(-o.w/2,-o.h/2,o.w,o.h); else ctx.strokeRect(-o.w/2,-o.h/2,o.w,o.h);} else if(d.shape==='triangle'){ctx.beginPath();ctx.moveTo(0,-o.h/2);ctx.lineTo(o.w/2,o.h/2);ctx.lineTo(-o.w/2,o.h/2);ctx.closePath(); if(d.fill) ctx.fill(); else ctx.stroke();} else if(d.shape==='star'){drawStarPath(ctx,0,0,o.w/2,o.h/2); if(d.fill) ctx.fill(); else ctx.stroke();} else if(d.shape==='heart'){drawHeartPath(ctx,-o.w/2,-o.h/2,o.w,o.h); if(d.fill) ctx.fill(); else ctx.stroke();} else { ctx.beginPath(); ctx.ellipse(0,0,o.w/2,o.h/2,0,0,Math.PI*2); if(d.fill) ctx.fill(); else ctx.stroke(); } }
   ctx.restore(); ctx.globalAlpha=1;
 };
 const composite=useCallback(()=>{
   const d=displayRef.current; if(!d) return;
   const ctx=d.getContext('2d'); if(!ctx) return;
   ctx.clearRect(0,0,d.width,d.height);
   if(!transparentBg){ctx.fillStyle=bgColor;ctx.fillRect(0,0,d.width,d.height);}
   if(showGridRef.current){ ctx.save(); ctx.strokeStyle='rgba(37,99,235,0.16)'; ctx.lineWidth=1; const gs=Math.max(5,gridSizeRef.current); for(let gx=gs;gx<d.width;gx+=gs){ ctx.beginPath(); ctx.moveTo(gx,0); ctx.lineTo(gx,d.height); ctx.stroke(); } for(let gy=gs;gy<d.height;gy+=gs){ ctx.beginPath(); ctx.moveTo(0,gy); ctx.lineTo(d.width,gy); ctx.stroke(); } ctx.restore(); }
   for(const l of layersRef.current){ if(!l.visible) continue; ctx.globalAlpha=l.opacity/100; ctx.drawImage(l.canvas,0,0); }
   ctx.globalAlpha=1;
   for(const o of objectsRef.current) drawOneObject(ctx,o, !!(editingGroupRef.current && o.id!==editingGroupRef.current));
   if(snapGuidesRef.current.length){ for(const g of snapGuidesRef.current){ if(g.axis==='x'||g.axis==='size'){ ctx.save(); ctx.strokeStyle=g.color; ctx.lineWidth=1.5; ctx.setLineDash([6,4]); ctx.beginPath(); ctx.moveTo(g.pos,0); ctx.lineTo(g.pos,d.height); ctx.stroke(); ctx.setLineDash([]); if(g.label){ ctx.fillStyle=g.color; ctx.font='bold 13px sans-serif'; ctx.fillRect(g.pos+4,6,ctx.measureText(g.label).width+12,20); ctx.fillStyle='#fff'; ctx.fillText(g.label,g.pos+10,20); } ctx.restore(); } else if(g.axis==='y'){ ctx.save(); ctx.strokeStyle=g.color; ctx.lineWidth=1.5; ctx.setLineDash([6,4]); ctx.beginPath(); ctx.moveTo(0,g.pos); ctx.lineTo(d.width,g.pos); ctx.stroke(); ctx.setLineDash([]); if(g.label){ ctx.fillStyle=g.color; ctx.font='bold 13px sans-serif'; ctx.fillRect(4,g.pos+4,ctx.measureText(g.label).width+12,20); ctx.fillStyle='#fff'; ctx.fillText(g.label,10,g.pos+18); } ctx.restore(); } else if(g.axis==='angle'){ ctx.save(); ctx.fillStyle=g.color; ctx.font='bold 16px sans-serif'; const txt=g.label; ctx.fillRect(d.width/2-34,10,68,26); ctx.fillStyle='#fff'; ctx.textAlign='center'; ctx.fillText(txt,d.width/2,28); ctx.restore(); } } }
   // Kotak seleksi TIDAK digambar di canvas: satu-satunya kotak seleksi
   // adalah overlay DOM di atas kanvas (left/top/width/height = x*zoom).
   // Dulu ada dua kotak (canvas biru putus-putus + DOM ungu) dengan
   // hitungan garis/handle berbeda (2/zoom, 26/zoom) sehingga terlihat
   // seperti satu kotak yang bergeser / meleset dari stikernya.
   if(marqueeRef.current){ const m=marqueeRef.current; ctx.save(); ctx.fillStyle='rgba(37,99,235,.18)'; ctx.strokeStyle='#2563eb'; ctx.lineWidth=1.5; ctx.fillRect(m.x,m.y,m.w,m.h); ctx.strokeRect(m.x,m.y,m.w,m.h); ctx.restore(); }
 },[transparentBg,bgColor,zoom]);

 useEffect(()=>{ layersRef.current=layers; activeRef.current=activeId; composite(); },[layers,activeId,composite]);
 useEffect(()=>{ objectsRef.current=objects; selectedRef.current=selectedIds; composite(); },[objects,selectedIds,composite]);
 const setObjectsBoth=(next:CanvasObject[])=>{ objectsRef.current=next; setObjects(next); // Gambar ulang kanvas SEGERA di frame yang sama (bukan menunggu
   // useEffect setelah paint): kalau tidak, overlay DOM bergerak di frame
   // ini sedangkan gambar objek baru bergerak di frame berikutnya, dan
   // kotak seleksi terlihat tertinggal / tidak nempel saat diseret.
   composite(); };
