   // Objek baru selalu ditambahkan di akhir daftar = paling atas.
   setObjectsBoth([...objectsRef.current,obj]);
   setSelectedBoth([obj.id]);
   selectTool('select');
   setSelectedSticker(null);
   setLastStickerKind(kind);
   setStickerPickerOpen(false);
   // Panaskan cache gambar stiker supaya langsung terlihat, bukan menunggu
   // giliran render berikutnya.
